//! 🧪️ Original terminal authority and ledger close separately with unchanged bounded policy.
use super::*;
#[repr(transparent)]
struct TerminalJob<const N:usize>([u8;N]);

struct TerminalSourceInitializer<const N:usize>{written:usize}
unsafe impl<const N:usize> WorkerJobInitializer<TerminalJob<N>> for TerminalSourceInitializer<N>{
 fn initialization_demand(&self,maximum_copy_bytes:usize)->Result<RetirementDemand,ValueError>{let cursor=0;let bytes=(N-self.written).min(maximum_copy_bytes.saturating_sub(cursor));Ok(RetirementDemand{copy_bytes:bytes+cursor,depth:1,..Default::default()})}
 unsafe fn initialize_step(&mut self,target:*mut MaybeUninit<TerminalJob<N>>,grant:RetainedCloneGrant)->Result<WorkerJobInitializationStep,ValueError>{let cursor=0;let bytes=(N-self.written).min(grant.maximum_copy_bytes.saturating_sub(cursor));if bytes==0&&self.written<N{return Ok(WorkerJobInitializationStep{progress:Default::default(),complete:false})}unsafe{std::ptr::write_bytes(target.cast::<u8>().add(self.written),7,bytes);}self.written+=bytes;Ok(WorkerJobInitializationStep{progress:RetainedCloneProgress{copied_items:1,copied_bytes:bytes+cursor,..Default::default()},complete:self.written==N})}
 fn initialization_input_is_empty(&self)->bool{true}
 fn partial_retirement_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 unsafe fn close_partial_step(&mut self,_:*mut MaybeUninit<TerminalJob<N>>,_:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Ok(RetainedCloneStep::Complete(Default::default()))}
 fn partial_terminal_is_empty(&self)->bool{true}

}
fn original_admission_turn<T>(params:&BatchJobParams,owner:impl FnOnce(&mut WorkerJobAdmissionContext<'_>)->T)->(T,RetainedCloneProgress){let entry=(params.now_us)().expect("original source clock must exist");let deadline=entry.checked_add(params.config.step_budget_us).expect("original deadline extent");let mut recipient=RetainedCloneProgress::default();let mut control=WorkerJobAdmissionContext::new(params.operation,params.generation,StepBudget::new(params.config.fuel_per_step,deadline,params.config.retained),params.now_us,&mut recipient).unwrap();let value=owner(&mut control);drop(control);assert!(recipient.fits(params.config.retained));(value,recipient)}
fn prepare_terminal_session<const N:usize>(params:BatchJobParams)->WorkerJobSession<TerminalJob<N>>{
 let identity=(params.operation,params.generation);let grant=params.config.retained;let clock=params.now_us;let fuel=params.config.fuel_per_step;let duration=params.config.step_budget_us;
 let mut storage=MaybeUninit::<WorkerJobSource<TerminalJob<N>>>::uninit();let mut recipient=RetainedCloneProgress::default();let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(fuel,clock().unwrap().checked_add(duration).unwrap(),grant),clock,&mut recipient).unwrap();let source=WorkerJobSource::start_preparation(&mut storage,&mut control).unwrap().unwrap().0;drop(control);assert!(recipient.fits(grant));let mut initializer=TerminalSourceInitializer::<N>{written:0};let mut turns=0;
 loop{let(step,_)=original_admission_turn(&params,|cx|source.prepare_step(&mut initializer,cx).unwrap());turns+=1;assert!(turns<64);if step.complete{break}}
 assert_eq!(source.source().unwrap().0,[7;N]);let pointer=source.source().unwrap()as*const _;let mut parameters=Some(params);let mut recipient=RetainedCloneProgress::default();let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(fuel,clock().unwrap().checked_add(duration).unwrap(),grant),clock,&mut recipient).unwrap();let(mut admission,progress)=WorkerJobAdmission::try_begin(source,&mut parameters,&mut control).unwrap().unwrap();drop(control);assert_eq!(recipient,progress);assert!(recipient.fits(grant));assert_eq!(admission.source()as*const _,pointer);
 let session=loop{let mut recipient=RetainedCloneProgress::default();let mut control=WorkerJobAdmissionContext::new(identity.0,identity.1,StepBudget::new(fuel,clock().unwrap().checked_add(duration).unwrap(),grant),clock,&mut recipient).unwrap();let(session,step)=admission.advance(&mut control).unwrap();drop(control);assert_eq!(recipient,step);assert!(step.fits(grant));turns+=1;assert!(turns<64);if let Some(session)=session{break session}assert_eq!(admission.source()as*const _,pointer);};drop(admission);assert!(parameters.is_none());assert!(source.source().is_none());session
}
impl<const N:usize> InteractiveJob for TerminalJob<N>{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{JobOutcomeBorrow::admit_yield(cx)}fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){JobOutcomeKind::Yield=>descriptor.yielded(),JobOutcomeKind::Cancelled=>descriptor.cancelled(),_=>Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture requires original yielded descriptor"))}}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:RetainedCloneGrant)->InteractiveJobCloseStep{InteractiveJobCloseStep::Complete{progress:Default::default()}}
 fn terminal_is_empty(&self)->bool{true}
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn authority_law<const N:usize>(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&fixture["policy"];
 let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 let cancel=root_cancel_token();let params=BatchJobParams{operation:OperationId(98120),generation:Generation(12),cancel:cancel.clone(),config:BatchDriveConfig{retained:grant,site:"test.original-authority",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000},now_us:default_now_us};
 let(mut authority,setup)=observe(||admit_original_fixture_owner!(WorkerJobAuthorityOwner,TerminalJob([7u8;N]),params).unwrap_or_else(|_|panic!("original authority admission")));let pointer=authority.0.as_ptr();let original_capacity=authority.0.capacity();let ledger_pointer=Arc::as_ptr(authority.payload_ledger.as_ref().unwrap());let mut physical=0;
 while !authority.preadmitted_fault.is_empty(){let(step,heap)=observe(||authority.preadmitted_fault.close_step(grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);physical+=heap.1;}
 let(_,heap)=observe(||{authority.job.remove_terminal(grant).unwrap();drop(authority.params.take());});assert_eq!(heap,(0,0));
 for phase in 0..2{
  let(demand,heap)=observe(||authority.terminal_authority_demands().unwrap());assert_eq!(heap,(0,0));assert!(demand.copy_bytes<=grant.maximum_copy_bytes);assert_eq!(authority.0.as_ptr(),pointer);assert_eq!(authority.0.capacity(),original_capacity);
  if phase==0{assert_eq!(Arc::as_ptr(authority.payload_ledger.as_ref().unwrap()),ledger_pointer);assert_eq!(demand.release_bytes,fixture["ledgerBytes"].as_u64().unwrap()as usize);}else{assert!(authority.payload_ledger.is_none());assert_eq!(demand.copy_bytes,fixture["bodyWords"].as_u64().unwrap()as usize*size_of::<usize>());assert_eq!(demand.release_bytes,original_capacity*size_of::<WorkerJobAuthority<TerminalJob<N>>>());}
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}].into_iter().filter(|denied|denied.maximum_items==0||denied.maximum_copy_bytes<demand.copy_bytes||denied.maximum_release_bytes<demand.release_bytes||denied.maximum_depth<demand.depth){let(step,heap)=observe(||authority.close_terminal_worker_authority(denied));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(authority.0.as_ptr(),pointer);assert_eq!(authority.0.capacity(),original_capacity);}
  let(step,heap)=observe(||authority.close_terminal_worker_authority(grant));let progress=step.progress();assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);assert_eq!(progress.released_bytes,demand.release_bytes);physical+=heap.1;
  if phase==0{assert!(matches!(step,WorkerJobCloseStep::Pending{..}));assert_eq!(authority.0.as_ptr(),pointer);}else{assert!(matches!(step,WorkerJobCloseStep::Complete{..}));assert!(authority.0.is_empty());assert_eq!(authority.0.capacity(),0);}
 }
 assert_eq!(physical,setup.0-setup.1);let(_,heap)=observe(||drop(authority));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Worker authority jobinline={N} samepointer preserved ledger128 separate backing physical={physical} copyheader={} body4096 terminalDrop0; semantic job/params transfer excluded",size_of::<Vec<WorkerJobAuthority<TerminalJob<N>>>>());
}
