fn worker_terminal_authority_retirement_preserves_original_ledger_then_in_place_backing(){authority_law::<0>();authority_law::<8192>();}

fn job_slot_law<const N:usize>(){
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut slot=WorkerJobSource::from_job(TerminalJob([7u8;N]),OperationId(99110),Generation(12));let pointer=slot.original().unwrap()as*const TerminalJob<N>;
 let(demand,heap)=observe(||slot.terminal_removal_demands());assert_eq!(heap,(0,0));assert_eq!(demand.copy_bytes,0);
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||slot.remove_terminal(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.original().unwrap()as*const TerminalJob<N>,pointer);assert_eq!(slot.original().unwrap().0,[7u8;N]);}
 let(step,heap)=observe(||slot.remove_terminal(grant).unwrap());assert_eq!(heap,(0,0));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(step.progress().copied_bytes,0);assert!(slot.is_empty());let(_,heap)=observe(||drop(slot));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Worker jobinline={N} pointer stable zero/below/depth and in-place presence1 body4096 terminalDrop0 no semantic carrier transfer");
}
